<div class="admin-head"><div><span class="eyebrow">LOGÍSTICA</span><h2 class="section">Gestión de pedidos</h2></div></div><div class="report-actions mb-3"><a class="btn grad" href="/?<?=e(http_build_query(array_merge($_GET,['r'=>'exportModule','module'=>'orders','type'=>'pdf'])))?>">Exportar PDF</a><a class="btn blue" href="/?<?=e(http_build_query(array_merge($_GET,['r'=>'exportModule','module'=>'orders','type'=>'excel'])))?>">Exportar Excel</a></div><form class="filter-strip" method="get"><input type="hidden" name="r" value="adminOrders"><input class="form-control" name="q" placeholder="Pedido, cliente o correo" value="<?=e($_GET['q']??'')?>"><select class="form-select searchable-select" name="status"><option value="">Todos los estados</option><?php foreach(['PEDIDO','PREPARACION','LISTO','EN_CAMINO','ENTREGADO','CANCELADO'] as $x):?><option value="<?=$x?>" <?=($_GET['status']??'')===$x?'selected':''?>><?=str_replace('_',' ',$x)?></option><?php endforeach;?></select><button class="btn blue">Filtrar</button></form><div class="card p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>#</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="/?r=orderDetail&id=<?=$o['id']?>">#<?=$o['id']?></a></td><td><?=e($o['fullname'])?></td><td>Q<?=number_format($o['total'],2)?></td><td><?=e($o['payment_status'])?></td><td><?=e($o['status'])?></td><td><form method="post" action="/?r=status" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select class="form-select searchable-select" name="status"><option value="" disabled selected>Nuevo estado</option><?php foreach(['PEDIDO','PREPARACION','LISTO','EN_CAMINO','ENTREGADO','CANCELADO'] as $x):?><option value="<?=$x?>"><?=$x?></option><?php endforeach;?></select><button class="btn blue">Guardar</button></form></td></tr><?php endforeach;?